// WF2 "Normalize": staging rows -> normalized, filtered, deduped leads (spec 6.3).
// The phone helper below is inlined at build time from lib/phone/egypt.mjs (single source of truth).
// Egyptian phone normalization. Plain ESM JS (JSDoc types) so the same source is inlined into n8n Code nodes.
// Stored form is E.164 with "+" (e.g. +201012345678). wa.me links use the digits without "+".
// WhatsApp-eligible = Egyptian MOBILE only (prefixes 010, 011, 012, 015). Landlines get a call action.

/**
 * @param {...(string|null|undefined)} candidates raw phone strings, best first (e.g. unformatted, then display)
 * @returns {{phone_raw: string|null, phone_e164: string|null, phone_type: 'mobile'|'landline'|'unknown', whatsapp_eligible: boolean}}
 */
function normalizeEgyptPhone(...candidates) {
  const phone_raw = candidates.find((c) => c && String(c).trim()) ?? null;
  for (const c of candidates) {
    if (!c) continue;
    let d = String(c).replace(/[٠-٩]/g, (x) => String(x.charCodeAt(0) - 0x0660)).replace(/\D/g, '');
    if (!d) continue;
    if (d.startsWith('0020')) d = d.slice(2); // 0020... -> 20...
    if (d.startsWith('20') && d.length >= 11 && d.length <= 12) d = d.slice(2); // national significant number
    else if (d.startsWith('0')) d = d.slice(1);
    // d is now the national number without the trunk 0
    if (/^1[0125]\d{8}$/.test(d)) {
      return { phone_raw, phone_e164: `+20${d}`, phone_type: 'mobile', whatsapp_eligible: true };
    }
    if (/^1\d{8,9}$/.test(d)) {
      // other mobile-looking numbers (e.g. 016, 017, 019 are not WhatsApp-eligible here)
      return { phone_raw, phone_e164: `+20${d}`, phone_type: 'unknown', whatsapp_eligible: false };
    }
    if (/^[2-9]\d{7,8}$/.test(d)) {
      return { phone_raw, phone_e164: `+20${d}`, phone_type: 'landline', whatsapp_eligible: false };
    }
  }
  return { phone_raw, phone_e164: null, phone_type: 'unknown', whatsapp_eligible: false };
}

/** wa.me link: digits only (no "+", no spaces) and the message URL-encoded. */
function whatsappLink(phoneE164, message) {
  const digits = String(phoneE164 || '').replace(/\D/g, '');
  if (!digits) return null;
  const text = message ? `?text=${encodeURIComponent(message)}` : '';
  return `https://wa.me/${digits}${text}`;
}

/** tel: link for landlines. */
function telLink(phoneE164) {
  return phoneE164 ? `tel:${phoneE164}` : null;
}


const body = $('Webhook').first().json.body;
const campaign = $('Get campaign').first().json;
const job = $('Get job').first().json;
const staging = $('Get staging').all().map((i) => i.json).filter((r) => r.external_id);

const f = (campaign.parameters || {}).filters || {};
const cap = Number((job.counts || {}).lead_cap) || 100;

const clean = (s) => (s == null ? null : String(s).replace(/[‎‏‪-‮]/g, '').trim() || null);
const gov = (s) => { const c = clean(s); return c ? c.replace(/^محافظة\s+/, '') : null; };
const lc = (s) => String(s || '').toLowerCase();

const stats = { staged: staging.length, filtered_out: 0, duplicates: 0, capped: 0 };
const seen = new Set();
const leads = [];

for (const row of staging) {
  const x = row.raw || {};
  const ph = normalizeEgyptPhone(x.phoneUnformatted, x.phone);
  const categories = [x.categoryName, ...(Array.isArray(x.categories) ? x.categories : [])].filter(Boolean).map(lc);
  const closed = !!(x.permanentlyClosed || x.temporarilyClosed);
  const website = clean(x.website);

  // campaign filters (spec 6.1)
  if (f.min_rating && !(Number(x.totalScore) >= Number(f.min_rating))) { stats.filtered_out++; continue; }
  if (f.min_reviews && !(Number(x.reviewsCount) >= Number(f.min_reviews))) { stats.filtered_out++; continue; }
  if (f.must_have_phone && !ph.phone_e164) { stats.filtered_out++; continue; }
  if (f.must_have_mobile && ph.phone_type !== 'mobile') { stats.filtered_out++; continue; }
  if (f.must_have_website && !website) { stats.filtered_out++; continue; }
  if (f.exclude_closed && closed) { stats.filtered_out++; continue; }
  if (Array.isArray(f.categories_include) && f.categories_include.length &&
      !f.categories_include.some((c) => categories.some((k) => k.includes(lc(c))))) { stats.filtered_out++; continue; }
  if (Array.isArray(f.categories_exclude) && f.categories_exclude.length &&
      f.categories_exclude.some((c) => categories.some((k) => k.includes(lc(c))))) { stats.filtered_out++; continue; }

  const district = clean(x.neighborhood) || x._district || null;
  const name = clean(x.title);
  // dedupe_key priority: place id, phone, email, name + district
  const dedupe_key = x.placeId ? `place:${x.placeId}`
    : ph.phone_e164 ? `phone:${ph.phone_e164}`
    : `name:${lc(name)}|${lc(district)}`;
  if (seen.has(dedupe_key)) { stats.duplicates++; continue; }
  seen.add(dedupe_key);

  if (leads.length >= cap) { stats.capped++; continue; }
  leads.push({
    business_name: name,
    category: clean(x.categoryName),
    address: clean(x.address),
    governorate: gov(x.state) || gov(x._governorate),
    city: clean(x.city) || x._city || null,
    district,
    lat: x.location?.lat ?? null,
    lng: x.location?.lng ?? null,
    phone_raw: ph.phone_raw,
    phone_e164: ph.phone_e164,
    phone_type: ph.phone_type,
    whatsapp_eligible: ph.whatsapp_eligible,
    website,
    email: null,
    facebook_url: null,
    instagram_url: null,
    linkedin_url: null,
    rating: x.totalScore ?? null,
    reviews_count: x.reviewsCount ?? null,
    opening_hours: x.openingHours ?? null,
    google_place_id: x.placeId || null,
    google_maps_url: x.url || null,
    contact_name: null,
    job_title: null,
    seniority: null,
    company_domain: null,
    source: 'google_maps',
    raw: x,
    dedupe_key,
  });
}

return [{ json: { p_org: body.organization_id, p_campaign: body.campaign_id, p_leads: leads, stats } }];

// WF2 "Counts": merge ingest results into job counts and decide the next step.
const ing = $input.first().json;
const norm = $('Normalize').first().json;
const job = $('Get job').first().json;
const campaign = $('Get campaign').first().json;
const body = $('Webhook').first().json.body;

const signals = ((campaign.parameters || {}).signals || []).filter((s) => s && Number(s.weight) !== 0);
const counts = {
  ...(job.counts || {}),
  staged: norm.stats.staged,
  filtered_out: norm.stats.filtered_out,
  duplicates_in_batch: norm.stats.duplicates,
  capped: norm.stats.capped,
  received: ing.received,
  dropped_opted_out: ing.dropped_opted_out,
  new: ing.new,
  already_known: ing.already_known,
  linked: ing.newly_linked,
};

return [{
  json: {
    job_id: body.job_id,
    campaign_id: body.campaign_id,
    organization_id: body.organization_id,
    counts,
    credits_used: ing.new, // 1 credit per NEW lead; leads already in the org are linked, not charged again
    signals_on: signals.length > 0,
    model: body.model,
    fallback_models: body.fallback_models,
  },
}];
